"use client"

import Link from "next/link"
import { usePathname } from "next/navigation"
import {
  Logout01Icon,
} from "@hugeicons/core-free-icons"
import { HugeiconsIcon } from "@hugeicons/react"

import {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerHeader,
  DrawerTitle,
} from "@/components/ui/drawer"
import { cn } from "@/lib/utils"
import {
  dashboardBrand,
  dashboardDocuments,
  dashboardNavMain,
  dashboardNavSecondary,
} from "../dashboard/dashboard-nav-config"

interface BottomDrawerProps {
  open: boolean
  onClose: () => void
}

export function BottomDrawer({ open, onClose }: BottomDrawerProps) {
  const pathname = usePathname()

  return (
    <Drawer open={open} onOpenChange={(nextOpen: boolean) => !nextOpen && onClose()}>
      <DrawerContent className="data-[vaul-drawer-direction=bottom]:max-h-[78vh]">
        <DrawerHeader className="gap-3 border-b px-4 pb-4">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-(--radius) bg-muted">
              <HugeiconsIcon
                icon={dashboardBrand.icon}
                size={20}
                strokeWidth={1.5}
              />
            </div>
            <div className="min-w-0">
              <DrawerTitle>{dashboardBrand.title}</DrawerTitle>
              <DrawerDescription className="text-sm text-muted-foreground">Navigation</DrawerDescription>
            </div>
          </div>
        </DrawerHeader>
        <div className="no-scrollbar overflow-y-auto px-4 pb-6">
          <nav className="space-y-6 pt-4">
            <section className="space-y-1">
              <p className="px-3 text-xs font-medium tracking-wide text-muted-foreground uppercase">
                Home
              </p>
              {dashboardNavMain.map((item) => (
                <DrawerClose asChild key={item.url}>
                  <Link
                    href={item.url}
                    onClick={onClose}
                    className={cn(
                      "flex items-center gap-3 rounded-(--radius) px-3 py-3 text-sm",
                      pathname === item.url
                        ? "bg-primary/10 font-medium text-primary"
                        : "text-muted-foreground hover:bg-accent hover:text-accent-foreground"
                    )}
                  >
                    <HugeiconsIcon
                      icon={item.icon}
                      size={20}
                      strokeWidth={1.5}
                    />
                    <span>{item.title}</span>
                  </Link>
                </DrawerClose>
              ))}
            </section>
            <section className="space-y-1">
              <p className="px-3 text-xs font-medium tracking-wide text-muted-foreground uppercase">
                Documents
              </p>
              {dashboardDocuments.map((item) => (
                <DrawerClose asChild key={item.url}>
                  <Link
                    href={item.url}
                    onClick={onClose}
                    className={cn(
                      "flex items-center gap-3 rounded-(--radius) px-3 py-3 text-sm",
                      pathname === item.url
                        ? "bg-primary/10 font-medium text-primary"
                        : "text-muted-foreground hover:bg-accent hover:text-accent-foreground"
                    )}
                  >
                    <HugeiconsIcon
                      icon={item.icon}
                      size={20}
                      strokeWidth={1.5}
                    />
                    <span>{item.name}</span>
                  </Link>
                </DrawerClose>
              ))}
            </section>
            <section className="space-y-1">
              <p className="px-3 text-xs font-medium tracking-wide text-muted-foreground uppercase">
                Support
              </p>
              {dashboardNavSecondary.map((item) => (
                <DrawerClose asChild key={item.url}>
                  <Link
                    href={item.url}
                    onClick={onClose}
                    className={cn(
                      "flex items-center gap-3 rounded-(--radius) px-3 py-3 text-sm",
                      pathname === item.url
                        ? "bg-primary/10 font-medium text-primary"
                        : "text-muted-foreground hover:bg-accent hover:text-accent-foreground"
                    )}
                  >
                    <HugeiconsIcon
                      icon={item.icon}
                      size={20}
                      strokeWidth={1.5}
                    />
                    <span>{item.title}</span>
                  </Link>
                </DrawerClose>
              ))}
            </section>
            <section className="space-y-1 border-t pt-4">
              <DrawerClose asChild>
                <Link
                  href="/logout"
                  onClick={onClose}
                  className="flex items-center gap-3 rounded-(--radius) px-3 py-3 text-sm text-muted-foreground hover:bg-accent hover:text-accent-foreground"
                >
                  <HugeiconsIcon
                    icon={Logout01Icon}
                    size={20}
                    strokeWidth={1.5}
                  />
                  <span>Log out</span>
                </Link>
              </DrawerClose>
            </section>
          </nav>
        </div>
      </DrawerContent>
    </Drawer>
  )
}
